INSERT INTO purpose VALUES('storage-artifact','build','function','Writes a record set''s index tree and value leaves into the store and names them with the manifest that carries the build''s kernel format, boundary commitment, record count, index root identity and the set''s naming.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','error::ArtifactError','enum','Names every way the artifact layer refuses an input: a kernel decoder refusal, a record-plane refusal, a malformed order, an unheld or unplaced record, names that do not match the places, a malformed or truncated manifest, trailing bytes, an unsupported kernel format, an incompatible profile, a tree mismatch, an order whose form is not the manifest''s, a misplaced record or a record off a segment boundary.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','error::ManifestField','enum','Names the field of a manifest image a refusal names, in image order: the domain, the manifest version, the kernel format, the commitment length, the commitment, the record count, the root node or the naming.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','manifest::ARTIFACT_IDENTITY_LEN','constant','Names the byte length of an artifact identity: one BLAKE3 output.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','manifest::ArtifactIdentity','struct','Holds the BLAKE3 identity of one artifact manifest image, deliberately its own type so a signature taking one never accepts a value manifest''s digest or a record-plane node identity.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','manifest::ArtifactManifest','struct','Holds the identity of one committed kernel artifact: the kernel format its records carry, the boundary commitment its index was cut under, the records it holds, the index root the order hangs from and the form of its names.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','manifest::ArtifactManifestVersion','struct','Names the layout version of an artifact manifest.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','manifest::MANIFEST_DOMAIN','constant','Names the domain every manifest image opens with, inside the hashed preimage.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','manifest::ManifestImage','struct','Holds the borrowed bytes offered to the manifest decoder.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','manifest::ManifestImageBuf','struct','Holds the owned image the manifest encoder writes, with the exact domain and supported version preceding fixed-width fields and a commitment whose declared length accounts for the entire image.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::ArtifactRecord','struct','Holds one declaration record: its segment''s bytes beside the identity of their value leaf, which is the record''s key.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::ArtifactRecordSet','struct','Holds the record set a kernel artifact is: its header, the order of its places, the content name of each place or why the set names none, and one record per distinct declaration segment, unique by key, in the order of its first place.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::CONTENT_NAME_LEN','constant','Names the byte width of a content name, the kernel''s content key of an entry.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::ContentName','struct','Holds the kernel''s content key of an entry, as the order of an artifact carries it beside a place.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::HEADER_KEY','constant','Names the key the header record is stored under: the empty key, which sorts first.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::Naming','enum','Names the form of an artifact''s names: every place named by the kernel''s content key of its entry, or none, for an export cut from bytes alone; an artifact never mixes the two.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::ORDER_KEY','constant','Names the key the order is stored under: one zero byte, which sorts after the header''s key and before every record key.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::Place','struct','Holds one place of the order: the slot of the record that stands there among the set''s keys.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::RECORD_KEY_LEN','constant','Names the byte width of a declaration record''s key, one node identity.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::ReassembledArtifact','struct','Holds the bytes a record set reassembles to: the header, then the segment at each place of the order.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::RecordKey','struct','Holds a declaration record''s key: the identity of the value leaf that holds the record''s bytes, so one key names one byte string in every artifact and no record stores its key beside its bytes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::SegmentBytes','struct','Holds the borrowed bytes of one artifact segment: the header, or one declaration''s.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::chain::CHUNK_CAP','constant','Names the most places one chunk of an order holds: eight times the chunker''s expected count of places for each cut.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::chain::CHUNK_KAPPA','constant','Names the chunker''s expected count of places for each content-defined cut of an order.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::chain::CHUNK_KEY_LEN','constant','Names the byte width of a chunk''s key: the order''s key byte, the identity of the chunk''s image and its occurrence.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::chain::StoredOrder','struct','Holds the order of a record set as its index tree stores it: the head, and each chunk''s record and leaf, in ascending order of their keys.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::kernel_names','function','Gives the kernel''s names of an artifact''s places from their content names: each place''s key when every place has one, and no name otherwise.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','record::unnamed','module','Names the reason a place has no name.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::CanonicalBytes','struct','Holds borrowed bytes with a width-checked length.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::CanonicalU64','struct','Holds the integer width admitted by the canonical step framing.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::StepIdEncoder','struct','Streams a domain-separated step preimage into a BLAKE3 digest, appending fixed-width big-endian integers and length-prefixed byte fields without retaining the preimage.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::StepIdError','enum','Names a refused transport image or canonical integer width: an identity image of the wrong byte length, or a count that cannot be represented in the canonical u64 width.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::TRANSPORT_STEP_ID_LEN','constant','Names the fixed width of a BLAKE3 step identity.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::TRANSPORT_STEP_MAGIC','constant','Names the domain and version included in every transport-step preimage.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::TransportStepId','struct','Holds a durable step digest, nominally distinct from build-local primitive labels.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::TransportStepIndex','struct','Holds a graded factorization keyed by durable step identity, retaining each factor''s local replay handle and multiplicity.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::TransportStepObstruction','enum','Names a refused resolution, encoding or collision at the transport boundary: a factor naming a cell absent from the store, a structural field past the canonical width, or one digest offered for distinct recorded factors.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::transport_step_id','function','Computes the durable identity of a certificate step by hashing its cell content and position under the domain-separated framing.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-artifact','transport::transport_step_index','function','Resolves and re-keys every normal-form factor under its durable identity, refusing an absent cell, a width overflow or a conflicting digest before returning any index.',NULL,'fits','sound',NULL);
